  FT["PH-H8653"] = {"id":"PH-H8653","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2012/ra_10200_2012.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"将南苏里高省 Bislig 市 San Roque 描笼涯 Mabog 村落的 Bislig 市国立中学的 Mabog 附属校分离，改设为独立的同名国立中学，并为此拨款","en":"An Act Separating the Bislig City National High School - Mabog Annex in Sitio Mabog, Barangay San Roque, City of Bislig, Province of Surigao Del Sur From the Bislig City National High School Converting It Into An Independent National High School to Be Known as Mabog National High School and Appropriating Funds Therefor","orig":"An Act Separating the Bislig City National High School - Mabog Annex in Sitio Mabog, Barangay San Roque, City of Bislig, Province of Surigao Del Sur From the Bislig City National High School Converting It Into An Independent National High School to Be Known as Mabog National High School and Appropriating Funds Therefor","vi":"Đạo luật tách Phân hiệu Mabog của Trường Trung học Thành phố Bislig Quốc gia tại Barangay San Roque, Thành phố Bislig, Tỉnh Surigao Del Sur khỏi Trường Trung học Thành phố Bislig Quốc gia và chuyển thành Trường Trung học Độc lập Quốc gia với tên gọi Trường Trung học Mabog Quốc gia, và bố trí kinh phí","th":"พระราชบัญญัติแยกวิทยาเขต Mabog ของโรงเรียนมัธยมศึกษาเมือง Bislig แห่งชาติในบารังไกย์ San Roque เมือง Bislig จังหวัด Surigao Del Sur ออกจากโรงเรียนมัธยมศึกษาเมือง Bislig แห่งชาติและยกฐานะเป็นโรงเรียนมัธยมศึกษาเอกเทศแห่งชาติชื่อโรงเรียนมัธยมศึกษา Mabog แห่งชาติ และจัดสรรงบประมาณ","id":"Undang-Undang Memisahkan Kampus Mabog, Sekolah Menengah Kota Bislig Nasional di Barangay San Roque, Kota Bislig, Provinsi Surigao Del Sur dari Sekolah Menengah Kota Bislig Nasional dan menjadi Sekolah Menengah Mandiri Nasional dengan nama Sekolah Menengah Mabog Nasional, dan mengalokasikan dana","ms":"Akta Memisahkan Kampus Mabog, Sekolah Menengah Bandar Bislig Kebangsaan di Barangay San Roque, Bandar Bislig, Wilayah Surigao Del Sur daripada Sekolah Menengah Bandar Bislig Kebangsaan dan menjadi Sekolah Menengah Bebas Kebangsaan dengan nama Sekolah Menengah Mabog Kebangsaan, dan memperuntukkan dana"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 10200","issuingBody":"Congress of the Philippines","promulgatedDate":"2012-10-18","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2012/ra_10200_2012.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8653-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Separation and Conversion into an Independent National High School. – The Bislig City National High School – Mabog Annex in Sitio Mabog, Barangay San Roque, City of Bislig, Province of Surigao del Sur is hereby separated from the Bislig City National High School and converted into an independent national high school to be known as Mabog National High School."}},{"id":"PH-H8653-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Transfer of Assets and Liabilities. – All personnel assets, liabilities and records of the Bislig City National High School –Mabog Annex are hereby transferred to and absorbed by the Mabog National High School."}},{"id":"PH-H8653-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Appropriations. – The Secretary of Education shall immediately include in the Department’s program the operationalization of the Mabog National High School, the initial funding of which shall be charged against the current year’s appropriation of the Bislig City National High School – Mabog Annex. Thereafter, the amount necessary for the continued operation of the school shall be included in the annual General Appropriations Act."}},{"id":"PH-H8653-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Implementation. – The Secretary of Education shall issue rules and regulations that may be necessary to carry out the purpose of this Act."}},{"id":"PH-H8653-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Effectivity. – This Act shall take effect fifteen (15) days after its publication in the Official Gazette."}}],"pack":"ph-p123","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Separating the Bislig City National High School - Mabog Annex in Sitio Mabog, Barangay San Roque, City of Bislig, Province of Surigao Del Sur From the Bislig City National High School Converting It Into An Independent National High School to Be Known as Mabog National High School and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H8654"] = {"id":"PH-H8654","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2012/ra_10201_2012.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Tadian市","en":"An Act Establishing a National High School in Barangay Balaoa, Municipality of Tadian, Mountain Province to Be Known as Balboa National High School and Appropriating Funds Therefor","orig":"An Act Establishing a National High School in Barangay Balaoa, Municipality of Tadian, Mountain Province to Be Known as Balboa National High School and Appropriating Funds Therefor","vi":"Đạo luật thành lập Trường trung học phổ thông quốc gia tại Barangay Balaoa, Thị trấn Tadian, Tỉnh Mountain được biết đến với tên gọi Trường trung học phổ thông quốc gia Balboa","th":"พระราชบัญญัติจัดตั้งโรงเรียนมัธยมศึกษาตอนปลายแห่งชาติในบารังไกย์ Balaoa, เทศบาล Tadian, จังหวัด Mountain ให้เป็นที่รู้จักในชื่อโรงเรียนมัธยมศึกษาตอนปลายแห่งชาติ Balboa","id":"Undang-Undang mendirikan Sekolah Menengah Atas Nasional di Barangay Balaoa, Kotamadya Tadian, Provinsi Mountain dikenal sebagai Sekolah Menengah Atas Nasional Balboa","ms":"Akta menubuhkan Sekolah Menengah Kebangsaan di Barangay Balaoa, Perbandaran Tadian, Wilayah Mountain dikenali sebagai Sekolah Menengah Kebangsaan Balboa"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 10201","issuingBody":"Congress of the Philippines","promulgatedDate":"2012-10-18","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2012/ra_10201_2012.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8654-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the supervision of the Department of Education, a national high school in Barangay Balaoa, Municipality of Tadian, Mountain Province to be known as Balaoa National High School."}},{"id":"PH-H8654-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Department of Education shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H8654-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Secretary of Education shall immediately include in the Department’s program the operationalization of the Balaoa National High School, the funding of which shall be included in the annual General Appropriations Act."}},{"id":"PH-H8654-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette."}}],"pack":"ph-p123"};
