  FT["PH-H8667"] = {"id":"PH-H8667","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2012/ra_10214_2012.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"将南三宝颜省 Pagadian 市 Buenavista 描笼涯的 Napolan 国立中学附属校分离，改设为独立的Norberta Guillar纪念国立中学，并为此拨付所需经费","en":"An Act Separating the Napolan National High School - Buenavista Annex in Barangay Buenavista, City of Pagadian, Province of Zamboanga Del Sur From the Napolan National High School, Converting It Into An Independent National High School to Be Known as Norberta Guillar Memorial National High School and Appropriating Funds Therefor","orig":"An Act Separating the Napolan National High School - Buenavista Annex in Barangay Buenavista, City of Pagadian, Province of Zamboanga Del Sur From the Napolan National High School, Converting It Into An Independent National High School to Be Known as Norberta Guillar Memorial National High School and Appropriating Funds Therefor","vi":"Đạo luật tách Phân hiệu Buenavista của Trường Trung học Napolan Quốc gia tại Barangay Buenavista, Thành phố Pagadian, Tỉnh Zamboanga Del Sur khỏi Trường Trung học Napolan Quốc gia và chuyển thành Trường Trung học Độc lập Quốc gia với tên gọi Trường Trung học Tưởng niệm Norberta Guillar Quốc gia, và bố trí kinh phí","th":"พระราชบัญญัติแยกวิทยาเขต Buenavista ของโรงเรียนมัธยมศึกษา Napolan แห่งชาติในบารังไกย์ Buenavista เมือง Pagadian จังหวัด Zamboanga Del Sur ออกจากโรงเรียนมัธยมศึกษา Napolan แห่งชาติและยกฐานะเป็นโรงเรียนมัธยมศึกษาเอกเทศแห่งชาติชื่อโรงเรียนมัธยมศึกษาอนุสรณ์ Norberta Guillar แห่งชาติ และจัดสรรงบประมาณ","id":"Undang-Undang Memisahkan Kampus Buenavista, Sekolah Menengah Napolan Nasional di Barangay Buenavista, Kota Pagadian, Provinsi Zamboanga Del Sur dari Sekolah Menengah Napolan Nasional dan menjadi Sekolah Menengah Mandiri Nasional dengan nama Sekolah Menengah Memorial Norberta Guillar Nasional, dan mengalokasikan dana","ms":"Akta Memisahkan Kampus Buenavista, Sekolah Menengah Napolan Kebangsaan di Barangay Buenavista, Bandar Pagadian, Wilayah Zamboanga Del Sur daripada Sekolah Menengah Napolan Kebangsaan dan menjadi Sekolah Menengah Bebas Kebangsaan dengan nama Sekolah Menengah Memorial Norberta Guillar Kebangsaan, dan memperuntukkan dana"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 10214","issuingBody":"Congress of the Philippines","promulgatedDate":"2012-10-18","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2012/ra_10214_2012.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8667-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Separation and Conversion into a National High School. – The Napolan National High School–Buenavista Annex in Barangay Buenavista, City of Pagadian, Province of Zamboanga del Sur is hereby separated from the Napolan National High School and converted into an independent national high school to be known as Norberta Guillar Memorial National High School."}},{"id":"PH-H8667-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Transfer of Assets and Liabilities. – All personnel, records, assets and liabilities of the Napolan National High School–Buenavista Annex are hereby transferred to and absorbed by the Norberta Guillar Memorial National High School."}},{"id":"PH-H8667-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Appropriations. – The Secretary of Education shall immediately include in the Department’s program the operationalization of the Norberta Guillar Memorial National High School, the initial funding of which shall be charged against the current year’s appropriation of the Napolan National High School–Buenavista Annex. Thereafter, the amount necessary for the continued operation of the school shall be included in the annual General Appropriations Act."}},{"id":"PH-H8667-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Implementation. – The Secretary of Education shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H8667-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Effectivity. – This Act shall take effect fifteen (15) days after its publication in the Official Gazette."}}],"pack":"ph-p123","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Separating the Napolan National High School - Buenavista Annex in Barangay Buenavista, City of Pagadian, Province of Zamboanga Del Sur From the Napolan National High School, Converting It Into An Independent National High School to Be Known as Norberta Guillar Memorial National High School and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H8668"] = {"id":"PH-H8668","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2012/ra_10215_2012.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Sindangan市","en":"An Act Establishing a National High School in Barangay R.G. Macias, Municipality of Sindangan, Province of Zamboanga Del Norte to Be Known as Doña Natividad L. Macias Memorial National High School and Appropriating Funds Therefor","orig":"An Act Establishing a National High School in Barangay R.G. Macias, Municipality of Sindangan, Province of Zamboanga Del Norte to Be Known as Doña Natividad L. Macias Memorial National High School and Appropriating Funds Therefor","vi":"Đạo luật thành lập Trường trung học phổ thông quốc gia tại Barangay R.G. Macias, Thị trấn Sindangan, Tỉnh Zamboanga Del Norte được biết đến với tên gọi Trường trung học phổ thông quốc gia Doña Natividad L. Macias Memorial","th":"พระราชบัญญัติจัดตั้งโรงเรียนมัธยมศึกษาตอนปลายแห่งชาติในบารังไกย์ R.G. Macias, เทศบาล Sindangan, จังหวัด Zamboanga Del Norte ให้เป็นที่รู้จักในชื่อโรงเรียนมัธยมศึกษาตอนปลายแห่งชาติ Doña Natividad L. Macias Memorial","id":"Undang-Undang mendirikan Sekolah Menengah Atas Nasional di Barangay R.G. Macias, Kotamadya Sindangan, Provinsi Zamboanga Del Norte dikenal sebagai Sekolah Menengah Atas Nasional Doña Natividad L. Macias Memorial","ms":"Akta menubuhkan Sekolah Menengah Kebangsaan di Barangay R.G. Macias, Perbandaran Sindangan, Wilayah Zamboanga Del Norte dikenali sebagai Sekolah Menengah Kebangsaan Doña Natividad L. Macias Memorial"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 10215","issuingBody":"Congress of the Philippines","promulgatedDate":"2012-10-18","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2012/ra_10215_2012.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8668-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Establishment of a National High School. – There is hereby established, under the supervision of the Department of Education, a national high school in Barangay R.G. Macias, Municipality of Sindangan, Province of Zamboanga del Norte to be known as Doña Natividad L. Macias Memorial National High School."}},{"id":"PH-H8668-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Appropriations. – The Secretary of Education shall immediately include in the Department’s program the operationalization of the Doña Natividad L. Macias Memorial National High School, the funding of which shall be included in the annual General Appropriations Act."}},{"id":"PH-H8668-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Implementation. – The Secretary of Education shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H8668-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Effectivity. – This Act shall take effect fifteen (15) days after its publication in the Official Gazette."}}],"pack":"ph-p123"};
